begin
 if (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public')<>730 then
   raise exception using errcode='23514',message='Installed public routine inventory changed.';end if;
 if (select count(distinct jsonb_build_array(v->>'name',v->>'arguments')) from jsonb_array_elements(expected_routines) v)<>jsonb_array_length(expected_routines) then
  raise exception using errcode='23514',message='Duplicate catalog routine identity in cutover manifest.';end if;
 select coalesce(jsonb_agg(v->>'identity'),'[]') into actual from jsonb_array_elements(expected_routines) v
 where not exists(select 1 from pg_proc x where x.pronamespace='public'::regnamespace and x.proname=v->>'name' and pg_get_function_identity_arguments(x.oid)=v->>'arguments');
 if jsonb_array_length(actual)<>0 then raise exception using errcode='23514',message='Installed routine identity preflight failed.',detail=actual::text;end if;
 for e in select value from jsonb_array_elements(expected_routines) loop
  select x.*,pg_get_userbyid(x.proowner) owner,l.lanname language into routine_record from pg_proc x join pg_language l on l.oid=x.prolang where x.pronamespace='public'::regnamespace and x.proname=e->>'name' and pg_get_function_identity_arguments(x.oid)=e->>'arguments';
  if routine_record.oid is null or encode(sha256(convert_to(routine_record.prosrc,'UTF8')),'hex') is distinct from e->>'bodySha256'
   or (case when routine_record.probin is not null then encode(sha256(convert_to(routine_record.probin,'UTF8')),'hex') end) is distinct from e->>'binarySha256'
   or routine_record.prosecdef is distinct from (e->>'securityDefiner')::boolean or routine_record.provolatile::text is distinct from e->>'volatility'
   or coalesce(to_jsonb(routine_record.proacl),'null'::jsonb) is distinct from e->'acl' or routine_record.owner is distinct from e->>'owner'
   or routine_record.language is distinct from e->>'language' or routine_record.prokind::text is distinct from e->>'kind'
   or (case when routine_record.proconfig is not null then encode(sha256(convert_to(routine_record.proconfig::text,'UTF8')),'hex') end) is distinct from e->>'configSha256' then
   raise exception using errcode='23514',message='Installed public authority drift requires review: '||(e->>'identity');end if;
 end loop;
 select coalesce(jsonb_agg(jsonb_build_object('table',c.oid::regclass::text,'name',t.tgname,'definition',pg_get_triggerdef(t.oid,true),'enabled',t.tgenabled::text) order by c.oid::regclass::text collate "C",t.tgname collate "C"),'[]') into actual
 from pg_trigger t join pg_class c on c.oid=t.tgrelid where not t.tgisinternal and c.oid::regclass::text in(select jsonb_array_elements_text($relations$["company_settings","cost_codes","custom_work_sessions","custom_work_units","flights","ground_transport","install_events","issues","locations","lodging","opening_phases","package_deliveries","packages","procedures","profiles","project_messages","project_openings","project_plansets","projects","qc_checks","safety_talks","sandbox_projects","schedule_assignment_members","schedule_assignments","service_cases","service_time_sessions","service_visit_units","service_visits","storage_containers","studio_projects","summon_helpers","summons","task_sessions","time_clock_actions","time_shifts","toolbox_completions","trip_attachments","trip_contacts","trip_crew","trips","unit_sessions","vehicle_project_assignments","vehicles","window_types","windows","work_activity_definitions","work_capture_menus","work_job_management_grants","work_job_menu_selections"]$relations$::jsonb));
 if actual is distinct from $triggers$[{"table":"cost_codes","name":"trg_cost_codes_updated","definition":"CREATE TRIGGER trg_cost_codes_updated BEFORE UPDATE ON cost_codes FOR EACH ROW EXECUTE FUNCTION set_cost_codes_updated_at()","enabled":"O"},{"table":"custom_work_sessions","name":"ai_clock_epoch_work","definition":"CREATE TRIGGER ai_clock_epoch_work AFTER INSERT OR DELETE ON custom_work_sessions FOR EACH ROW EXECUTE FUNCTION _ai_bump_clock_epoch('profile_id')","enabled":"O"},{"table":"custom_work_sessions","name":"ai_clock_epoch_work_update","definition":"CREATE TRIGGER ai_clock_epoch_work_update AFTER UPDATE ON custom_work_sessions FOR EACH ROW WHEN (old.profile_id IS DISTINCT FROM new.profile_id OR old.ended_at IS DISTINCT FROM new.ended_at OR old.unit_id IS DISTINCT FROM new.unit_id OR old.stage IS DISTINCT FROM new.stage OR old.participation IS DISTINCT FROM new.participation) EXECUTE FUNCTION _ai_bump_clock_epoch('profile_id')","enabled":"O"},{"table":"custom_work_sessions","name":"guard_test_account_sandbox_only","definition":"CREATE TRIGGER guard_test_account_sandbox_only BEFORE INSERT OR DELETE OR UPDATE ON custom_work_sessions FOR EACH ROW EXECUTE FUNCTION guard_test_account_sandbox_only('project_id', 'project')","enabled":"O"},{"table":"custom_work_sessions","name":"service_custom_work","definition":"CREATE TRIGGER service_custom_work BEFORE INSERT OR UPDATE OF ended_at ON custom_work_sessions FOR EACH ROW EXECUTE FUNCTION service_follow_work()","enabled":"O"},{"table":"custom_work_units","name":"custom_work_units_one_owner","definition":"CREATE TRIGGER custom_work_units_one_owner BEFORE INSERT OR UPDATE OF opening_id, assigned_to ON custom_work_units FOR EACH ROW EXECUTE FUNCTION _ai_one_unit_owner()","enabled":"O"},{"table":"custom_work_units","name":"guard_test_account_sandbox_only","definition":"CREATE TRIGGER guard_test_account_sandbox_only BEFORE INSERT OR DELETE OR UPDATE ON custom_work_units FOR EACH ROW EXECUTE FUNCTION guard_test_account_san